// RedactionBatch holds the trace IDs for an in-flight redaction submission.
// All pending block jobs for a tenant share one batch to avoid copying the trace ID
// list into every job (which could be millions of jobs for large tenants).
// Persisted locally as batches.pb alongside the shard files.
type RedactionBatch struct {
	BatchId           string   `protobuf:"bytes,1,opt,name=batch_id,json=batchId,proto3" json:"batch_id,omitempty"`
	TenantId          string   `protobuf:"bytes,2,opt,name=tenant_id,json=tenantId,proto3" json:"tenant_id,omitempty"`
	TraceIds          [][]byte `protobuf:"bytes,3,rep,name=trace_ids,json=traceIds,proto3" json:"trace_ids,omitempty"`
	CreatedAtUnixNano int64    `protobuf:"varint,4,opt,name=created_at_unix_nano,json=createdAtUnixNano,proto3" json:"created_at_unix_nano,omitempty"`
	// skipped_compaction_job_ids holds the IDs of compaction jobs whose input
	// blocks were skipped at submission time because they were actively compacting.
	// At rescan time the scheduler looks up these jobs and creates redaction jobs
	// for their output blocks.
	SkippedCompactionJobIds []string `protobuf:"bytes,5,rep,name=skipped_compaction_job_ids,json=skippedCompactionJobIds,proto3" json:"skipped_compaction_job_ids,omitempty"`
	// rescan_after_unix_nano is the earliest time at which the scheduler should
	// perform the rescan described above. Zero means no rescan is pending.
	RescanAfterUnixNano int64 `protobuf:"varint,6,opt,name=rescan_after_unix_nano,json=rescanAfterUnixNano,proto3" json:"rescan_after_unix_nano,omitempty"`
	// query, when set, selects traces via a TraceQL expression instead of trace_ids.
	// Stored in the manifest for the lifetime of the redaction and injected into each
	// per-block job.
	Query *TraceQLSelector `protobuf:"bytes,7,opt,name=query,proto3" json:"query,omitempty"`
	// mode selects apply (default) vs dry-run for the whole batch.
	Mode RedactionMode `protobuf:"varint,8,opt,name=mode,proto3,enum=tempopb.RedactionMode" json:"mode,omitempty"`
	// quiesce_until_unix_nano holds a completed batch open until this deadline before removal,
	// so compaction stays disabled long enough for the rescan to catch any block a compaction
	// produced just as the last redaction job finished. 0 means the batch is not yet in
	// quiescence (still in progress); it is set once when all jobs complete, and the batch is
	// removed on the first maintenance tick at or after the deadline. An absolute timestamp is
	// stable across pod restarts / work reloads and avoids rewriting the batch on every tick.
	QuiesceUntilUnixNano int64 `protobuf:"varint,9,opt,name=quiesce_until_unix_nano,json=quiesceUntilUnixNano,proto3" json:"quiesce_until_unix_nano,omitempty"`
	// cancelled marks a batch whose queued jobs were discarded by CancelRedaction. Jobs already
	// running on a worker still finish, so an apply-mode batch may have rewritten blocks; it
	// therefore still quiesces (only a dry-run, which rewrites nothing, skips that). No rescan is
	// performed: the blocks a cancel abandons are deliberately left un-redacted.
	Cancelled bool `protobuf:"varint,10,opt,name=cancelled,proto3" json:"cancelled,omitempty"`
}

